async function boot(){try{const responses=await Promise.all([fetch('./assets/sprites.svg'),fetch('./assets/board.svg')]);if(responses.some(r=>!r.ok))throw Error('Assets unavailable');const loadImage=url=>new Promise((resolve,reject)=>{const i=new Image();i.onload=resolve;i.onerror=reject;i.src=url});await Promise.all(['./assets/towers-atlas.png','./assets/enemies-atlas.png','./assets/garden.png','./assets/icons-atlas.png','./assets/ammo-atlas.png'].map(loadImage));const [sprites,board]=await Promise.all(responses.map(r=>r.text()));document.body.insertAdjacentHTML('afterbegin',sprites);document.getElementById('mapMount').innerHTML=board;await (await import('./art.js')).prepareRasterImages();await import('./game.js');document.getElementById('loading').remove()}catch(e){console.error(e);document.getElementById('loading').innerHTML='<div class="loadPizza">Кухня ещё прогревается</div><p>Не удалось загрузить игру.</p><button onclick="location.reload()">Попробовать снова</button>'}}boot();